"""Shared network layer for us-legal-sources scripts (stdlib only).

Every live request made by fetch_doc.py and ingest.py goes through `get()`:

* **Allowlist.** The host must appear in hosts.json (generated by build.py from
  data/*.json). A host whose every row is BLOCKED is refused outright.
* **robots.txt.** Checked per URL (paths AND query strings — Delaware's
  robots.txt disallows individual opinion ids), case-insensitively, for
  user-agent `*` and our own token. Unreachable robots.txt (5xx/timeout) is
  treated as "disallow everything", as the skill's fetch tool does.
* **Refusals are final.** 401/403/429/451, a Cloudflare challenge
  (`cf-mitigated: challenge`) or an HTML bot-check page instead of the
  expected document → RefusedError, recorded in the cache so nothing else in
  the run tries that host again. Never retried by another route.
* **Politeness.** At least 1.1 s between requests to one host across every
  process sharing the cache (lock file), or the host's Crawl-delay if larger.
* **Cache.** Responses are cached on disk (default 1 day) keyed by URL.
"""
import fcntl
import hashlib
import json
import os
import re
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

UA_TOKEN = "deep-legal-research-resources"
USER_AGENT = (f"{UA_TOKEN}/1.0 (legal research; respects robots.txt; "
              "+https://github.com/jumpingtom1/deep-legal-research-resources)")
ROOT = Path(__file__).resolve().parent.parent
CACHE = Path(os.environ.get("LEGAL_SOURCES_CACHE",
                            Path.home() / ".cache" / "us-legal-sources"))
MIN_GAP = 1.1
TIMEOUT = 60
REFUSE_CODES = {401, 403, 451}          # 429 is 'slow down', handled separately


class RefusedError(Exception):
    """The host or URL may not be fetched. Do not try another route."""


class FetchError(Exception):
    """Transient failure (network, 5xx, 404)."""


def _cache_dir(*parts):
    p = CACHE.joinpath(*parts)
    p.mkdir(parents=True, exist_ok=True)
    return p


# ------------------------------------------------------------------ allowlist
def load_hosts(path=None):
    path = Path(path or os.environ.get("LEGAL_SOURCES_HOSTS", ROOT / "hosts.json"))
    if not path.exists():
        raise FetchError(f"no host allowlist at {path} — run scripts/build.py "
                         "or set LEGAL_SOURCES_HOSTS")
    return json.loads(path.read_text())["hosts"]


def check_allowlist(url, hosts=None):
    host = urllib.parse.urlsplit(url).hostname or ""
    hosts = hosts if hosts is not None else load_hosts()
    h = hosts.get(host.lower())
    if h is None:
        raise RefusedError(f"{host} is not on the deep-legal-research-resources allowlist "
                           "(no jurisdiction record names it). Do not fetch it "
                           "by any other route.")
    if h["status"] == "blocked":
        raise RefusedError(f"{host} is recorded as BLOCKED ({'; '.join(h['sources'])}). "
                           "Never fetched by any route.")
    return h


# ------------------------------------------------------------------ refusals
def _refused_file():
    return _cache_dir() / "refused.json"


def _refused():
    f = _refused_file()
    try:
        return json.loads(f.read_text())
    except Exception:
        return {}


def mark_refused(host, reason):
    """host may be a hostname (host-wide refusal) or a full URL (that URL only)."""
    d = _refused()
    d[host] = {"reason": reason, "at": time.strftime("%Y-%m-%dT%H:%M:%S")}
    _refused_file().write_text(json.dumps(d, indent=1))


def check_not_refused(host):
    r = _refused().get(host)
    if r and time.time() - time.mktime(time.strptime(r["at"], "%Y-%m-%dT%H:%M:%S")) < 86400:
        scope = "this address" if "://" in host else "this host"
        raise RefusedError(f"{host} refused automated access earlier "
                           f"({r['reason']}, {r['at']}); {scope} is off for the rest of the day.")


# ------------------------------------------------------------------ politeness
def _wait_turn(host, gap):
    lock = _cache_dir("locks") / f"{host}.lock"
    with open(lock, "a+") as fh:
        fcntl.flock(fh, fcntl.LOCK_EX)
        fh.seek(0)
        try:
            last = float(fh.read().strip() or 0)
        except ValueError:
            last = 0
        delay = last + gap - time.time()
        if delay > 0:
            time.sleep(delay)
        fh.seek(0)
        fh.truncate()
        fh.write(str(time.time()))
        fh.flush()
        fcntl.flock(fh, fcntl.LOCK_UN)


# ------------------------------------------------------------------ robots
def _raw_request(url):
    req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT,
                                               "Accept": "*/*"})
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as r:
            return r.status, dict(r.headers), r.read(), r.geturl()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers or {}), e.read() if e.fp else b"", url


def _parse_robots(text):
    """Return (rules, crawl_delay) for the group matching us or '*'."""
    groups, cur, agents, last_was_agent = [], None, [], False
    # Honour the evident intent of malformed files that put several directives
    # on one line ("User-agent: * Disallow: /" — codes.ohio.gov): split them.
    text = re.sub(r"\s+(?=(?:user-agent|disallow|allow|crawl-delay|sitemap)\s*:)",
                  "\n", text, flags=re.I)
    for line in text.splitlines():
        line = line.split("#", 1)[0].strip()
        if ":" not in line:
            continue
        k, v = (x.strip() for x in line.split(":", 1))
        k = k.lower()
        if k == "user-agent":
            if not last_was_agent:
                cur = {"agents": [], "rules": [], "delay": None}
                groups.append(cur)
            cur["agents"].append(v.lower())
            last_was_agent = True
            continue
        last_was_agent = False
        if cur is None:
            continue
        if k in ("allow", "disallow"):
            cur["rules"].append((k, v))
        elif k == "crawl-delay":
            try:
                cur["delay"] = float(v)
            except ValueError:
                pass
    mine = [g for g in groups if any(UA_TOKEN in a for a in g["agents"])]
    star = [g for g in groups if "*" in g["agents"]]
    chosen = mine or star
    rules = [r for g in chosen for r in g["rules"]]
    delays = [g["delay"] for g in chosen if g["delay"]]
    return rules, (max(delays) if delays else None)


def _rule_matches(pattern, target):
    if pattern == "":
        return False
    rx = re.escape(pattern).replace(r"\*", ".*")
    if rx.endswith(r"\$"):
        rx = rx[:-2] + "$"
    return re.match(rx, target, re.I) is not None   # case-insensitive on purpose


def _is_storage_no_file(hl, body):
    server = hl.get("server", "")
    if "Windows-Azure-Blob" in server and hl.get("x-ms-error-code") in (
            "NoAuthenticationInformation", "ResourceNotFound", "BlobNotFound",
            "PublicAccessNotPermitted", "AuthorizationFailure"):
        return True
    if server in ("AmazonS3",) and b"<Code>AccessDenied</Code>" in body[:600]:
        return True
    if "UploadServer" in server and b"<Code>AccessDenied</Code>" in body[:600]:   # GCS
        return True
    return False


def robots_check(url):
    """Raise RefusedError if robots.txt disallows url. Returns crawl delay."""
    parts = urllib.parse.urlsplit(url)
    host = parts.hostname.lower()
    cache = _cache_dir("robots") / f"{host}.json"
    data = None
    if cache.exists() and time.time() - cache.stat().st_mtime < 86400:
        data = json.loads(cache.read_text())
    if data is None:
        robots_url = f"{parts.scheme}://{parts.netloc}/robots.txt"
        code, headers, body = 599, {}, b""
        for attempt in (1, 2):          # one retry for a transient failure
            _wait_turn(host, MIN_GAP)
            try:
                code, headers, body, _ = _raw_request(robots_url)
            except Exception as e:
                code, headers, body = 599, {}, str(e).encode()
                if b"CERTIFICATE_VERIFY_FAILED" in body:
                    raise FetchError(f"{host}: TLS certificate chain does not verify from "
                                     "this sandbox (often a server missing its intermediate "
                                     "certificate). Verification is never disabled — use the "
                                     "next route.")
            if code < 500:
                break
        hl = {k.lower(): v for k, v in headers.items()}
        if hl.get("cf-mitigated", "").lower() == "challenge":
            data = {"status": "challenge", "rules": [], "delay": None}
        elif code in (401, 403) and _is_storage_no_file(hl, body):
            # RFC 9309: a 4xx on robots.txt means "no rules". Cloud object stores
            # (Azure Blob, S3, GCS) answer 401/403 with an XML error when a public
            # container simply has no robots.txt — that is not a bot wall.
            data = {"status": "none", "rules": [], "delay": None,
                    "note": f"no robots.txt (storage service, HTTP {code})"}
        elif code in (401, 403):
            # Any other 401/403 on robots.txt is in practice a bot wall; refuse.
            data = {"status": "refused", "rules": [], "delay": None}
        elif 400 <= code < 500:
            data = {"status": "none", "rules": [], "delay": None}
        elif code >= 500:
            data = {"status": "unreachable", "rules": [], "delay": None}
        else:
            rules, delay = _parse_robots(body.decode("utf-8", "replace"))
            data = {"status": "ok", "rules": rules, "delay": delay}
        if data["status"] != "unreachable":     # never cache a transient failure
            cache.write_text(json.dumps(data))
    st = data["status"]
    if st in ("challenge", "refused"):
        mark_refused(host, f"robots.txt {st}")
        raise RefusedError(f"{host} answers robots.txt with a bot check ({st}); "
                           "automated access refused.")
    if st == "unreachable":
        raise FetchError(f"robots.txt on {host} unreachable after a retry "
                         f"({body[:120].decode('utf-8', 'replace')}) — not fetching; try later.")
    target = parts.path or "/"
    if parts.query:
        target += "?" + parts.query
    best = None
    for kind, pat in data["rules"]:
        if _rule_matches(pat, target):
            if best is None or len(pat) > len(best[1]) or (
                    len(pat) == len(best[1]) and kind == "allow"):
                best = (kind, pat)
    if best and best[0] == "disallow":
        raise RefusedError(f"robots.txt on {host} disallows {target} "
                           f"(rule: Disallow: {best[1]}).")
    return data.get("delay")


# ------------------------------------------------------------------ get
def _looks_like_bot_wall(headers, body, expect):
    hl = {k.lower(): v for k, v in headers.items()}
    if hl.get("cf-mitigated", "").lower() == "challenge":
        return "Cloudflare challenge"
    ctype = hl.get("content-type", "").lower()
    if expect == "pdf" and "pdf" not in ctype and not body[:5] == b"%PDF-":
        sniff = body[:4000].decode("utf-8", "replace").lower()
        if any(s in sniff for s in ("captcha", "challenge", "verify you are human",
                                     "access denied", "enable javascript")):
            return "bot-check page served instead of the PDF"
        return f"expected a PDF, got {ctype or 'unknown type'}"
    return None


def get(url, *, expect=None, max_age=86400, hosts=None, allow_unlisted=False):
    """Fetch url politely. Returns dict(body, headers, final_url, cached, sha256)."""
    parts = urllib.parse.urlsplit(url)
    if parts.scheme != "https":
        url = urllib.parse.urlunsplit(("https",) + tuple(parts[1:]))
        parts = urllib.parse.urlsplit(url)
    host = parts.hostname.lower()
    if not allow_unlisted:
        check_allowlist(url, hosts)
    check_not_refused(host)
    check_not_refused(url)
    key = hashlib.sha256(url.encode()).hexdigest()[:32]
    cdir = _cache_dir("docs")
    meta_f, body_f = cdir / f"{key}.json", cdir / f"{key}.bin"
    if meta_f.exists() and body_f.exists() and time.time() - meta_f.stat().st_mtime < max_age:
        meta = json.loads(meta_f.read_text())
        body = body_f.read_bytes()
        return {**meta, "body": body, "cached": True}
    delay = robots_check(url)
    err = None
    for attempt in (1, 2):              # one retry for a transient failure
        _wait_turn(host, max(MIN_GAP, delay or 0))
        try:
            code, headers, body, final = _raw_request(url)
            err = None
            if code < 500:
                break
        except Exception as e:
            err = e
            if "CERTIFICATE_VERIFY_FAILED" in str(e):
                break                   # not transient; never retried without verification
    if err is not None:
        if "CERTIFICATE_VERIFY_FAILED" in str(err):
            raise FetchError(f"{host}: TLS certificate chain does not verify from this "
                             "sandbox (often a server missing its intermediate certificate). "
                             "Verification is never disabled — use the next route.")
        raise FetchError(f"network error fetching {url} (after a retry): {err}")
    final_host = (urllib.parse.urlsplit(final).hostname or "").lower()
    if final_host != host:
        # A redirect to another host is only followed if that host is allowed
        # and its robots.txt permits the path — otherwise refused.
        if not allow_unlisted:
            check_allowlist(final, hosts)
        check_not_refused(final_host)
        robots_check(final)
    if code == 429:
        ra = {k.lower(): v for k, v in headers.items()}.get("retry-after", "")
        raise FetchError(f"{host} is rate-limiting (HTTP 429"
                         + (f", Retry-After {ra}s" if ra else "") + "). Not a refusal: "
                         "wait and try again later, or use the next route.")
    if code in REFUSE_CODES:
        reason = f"HTTP {code}"
        hl = {k.lower(): v for k, v in headers.items()}
        if hl.get("cf-mitigated", "").lower() == "challenge":
            # A bot challenge is a host-wide policy: off for the day.
            reason += " (Cloudflare challenge)"
            mark_refused(final_host or host, reason)
            raise RefusedError(f"{final_host or host} refused automated access: {reason}. "
                               "Do not retry by another route.")
        # A plain 401/403/451 on one document refuses that document only.
        mark_refused(final, reason)
        raise RefusedError(f"{final} refused: {reason}. Do not retry this address by "
                           "another route; other pages on the host are unaffected.")
    if code >= 400:
        raise FetchError(f"HTTP {code} for {url}")
    wall = _looks_like_bot_wall(headers, body, expect)
    if wall and ("challenge" in wall or "bot-check" in wall):
        mark_refused(final_host or host, wall)
        raise RefusedError(f"{final_host or host}: {wall}. Do not retry by another route.")
    if wall:
        raise FetchError(f"{url}: {wall}")
    meta = {"url": url, "final_url": final, "status": code,
            "headers": {k: v for k, v in headers.items()
                        if k.lower() in ("content-type", "last-modified", "etag",
                                         "content-disposition", "content-length")},
            "fetched_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
            "sha256": hashlib.sha256(body).hexdigest(), "bytes": len(body)}
    body_f.write_bytes(body)
    meta_f.write_text(json.dumps(meta))
    return {**meta, "body": body, "cached": False}
